cd /app && python - <<'PY'
import sys; sys.path.insert(0,'/tmp')
import numpy as np
from test_final import steal, A
for seed in [2,9]:
 R,cls=steal(seed=seed,nlines=60,M=120)
 print('SEED',seed, 'nclusters',len(cls))
 for j,(cl,r) in enumerate(zip(cls,R)):
    best=-1; bi=None
    for i,row in enumerate(A):
        u=row/np.linalg.norm(row); c=abs(r@u)
        if c>best: best=c; bi=i
    if len(cl['U'])>=5:
        print(j,'sup',len(cl['U']),'bestrow',bi,'cos',round(best,8))
PY
